import React from 'react';

function Header({ paginaActual, navegar, carrito, usuario, cerrarSesion }) {
  const styles = {
    header: {
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
      padding: '15px 30px',
      position: 'sticky',
      top: 0,
      zIndex: 1000,
      boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
      borderBottom: '3px solid #ff6b00'
    },
    navContainer: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '15px'
    },
    logo: {
      fontSize: '28px',
      fontWeight: '900',
      color: '#ff6b00',
      cursor: 'pointer'
    },
    nav: {
      display: 'flex',
      gap: '25px',
      alignItems: 'center',
      flexWrap: 'wrap'
    },
    navLink: {
      color: '#ffffff',
      fontWeight: '600',
      fontSize: '15px',
      padding: '8px 15px',
      borderRadius: '8px',
      cursor: 'pointer',
      textTransform: 'uppercase'
    },
    carritoIcon: {
      position: 'relative',
      cursor: 'pointer',
      fontSize: '24px'
    },
    badge: {
      position: 'absolute',
      top: '-8px',
      right: '-8px',
      backgroundColor: '#ff6b00',
      color: 'white',
      borderRadius: '50%',
      width: '22px',
      height: '22px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '12px',
      fontWeight: 'bold'
    }
  };

  return (
    <header style={styles.header}>
      <div style={styles.navContainer}>
        <span onClick={() => navegar('home')} style={styles.logo}>
          🏍️ MotoZone Pro
        </span>
        <nav style={styles.nav}>
          <span onClick={() => navegar('home')} style={{...styles.navLink, backgroundColor: paginaActual === 'home' ? '#ff6b00' : 'transparent'}}>Inicio</span>
          <span onClick={() => navegar('productos')} style={{...styles.navLink, backgroundColor: paginaActual === 'productos' ? '#ff6b00' : 'transparent'}}>Productos</span>
          <span onClick={() => navegar('contacto')} style={{...styles.navLink, backgroundColor: paginaActual === 'contacto' ? '#ff6b00' : 'transparent'}}>Contacto</span>
          <div style={styles.carritoIcon} onClick={() => navegar('carrito')}>
            🛒
            {carrito.length > 0 && (
              <span style={styles.badge}>
                {carrito.reduce((acc, item) => acc + item.cantidad, 0)}
              </span>
            )}
          </div>
          {usuario ? (
            <span style={{color: 'white'}}>👤 {usuario.nombre} <button onClick={cerrarSesion} style={{marginLeft: '10px', padding: '5px 10px', backgroundColor: '#e53e3e', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer'}}>Salir</button></span>
          ) : (
            <span onClick={() => navegar('login')} style={{...styles.navLink, backgroundColor: '#ff6b00'}}>Login</span>
          )}
        </nav>
      </div>
    </header>
  );
}

export default Header;
